{
  "apiVersion": 1,
  "type": "component.detail.props",
  "package": "@astryxdesign/core",
  "data": [
    {
      "name": "value",
      "type": "string",
      "description": "Unique value used for item identity, highlight lookup, and selection.",
      "required": true
    },
    {
      "name": "children",
      "type": "ReactNode",
      "description": "Non-interactive item content such as a label, icon, description, or keyboard shortcut.",
      "required": true
    },
    {
      "name": "onSelect",
      "type": "(value: string) => void",
      "description": "Called after this item is activated by pointer. Keyboard selection in CommandPalette reports through CommandPalette onValueChange."
    },
    {
      "name": "isHighlighted",
      "type": "boolean",
      "description": "Whether this item is the active keyboard result. Derived from context when omitted inside CommandPalette.",
      "default": "false"
    },
    {
      "name": "isSelected",
      "type": "boolean",
      "description": "Whether this item represents the selected value in picker mode. Derived from the CommandPalette value when omitted inside CommandPalette.",
      "default": "false"
    },
    {
      "name": "isDisabled",
      "type": "boolean",
      "description": "Whether the item is unavailable and suppresses pointer activation.",
      "default": "false"
    },
    {
      "name": "xstyle",
      "type": "StyleXStyles",
      "description": "StyleX styles for layout customization. Must be a stylex.create() value."
    }
  ],
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
